INSERT INTO member_team_history (
    member_id, previous_team_id, new_team_id, reason, changed_by_member_id, changed_dttm
) VALUES (
    #{memberId}, #{previousTeamId}, #{newTeamId}, #{reason}, #{changedByMemberId}, #{changedDttm}
)

INSERT INTO member_role_history (
    member_id, previous_role_code, new_role_code, reason, changed_by_member_id, changed_dttm
) VALUES (
    #{memberId}, #{previousRole}, #{newRole}, #{reason}, #{changedByMemberId}, #{changedDttm}
)

INSERT INTO member_cohort_history (
    member_id, previous_cohort_id, new_cohort_id, reason, changed_by_member_id, changed_dttm
) VALUES (
    #{memberId}, #{previousCohortId}, #{newCohortId}, #{reason}, #{changedByMemberId}, #{changedDttm}
)

INSERT INTO member_status_history (
    member_id, previous_status_code, new_status_code, reason, changed_by_member_id, changed_dttm
) VALUES (
    #{memberId}, #{previousStatus}, #{newStatus}, #{reason}, #{changedByMemberId}, #{changedDttm}
)
